CREATE TABLE public.followup_enrollments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    pointer_id uuid NOT NULL,
    version_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    conversation_id uuid,
    current_node_id text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    next_eval_at timestamp with time zone DEFAULT now(),
    claimed_until timestamp with time zone,
    attempts smallint DEFAULT 0 NOT NULL,
    max_attempts smallint DEFAULT 5 NOT NULL,
    last_error text,
    steps_taken smallint DEFAULT 0 NOT NULL,
    outcome text,
    cancel_reason text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    agent_id uuid,
    timing_plan jsonb,
    CONSTRAINT followup_enrollments_outcome_check CHECK ((outcome = ANY (ARRAY['converted'::text, 'replied'::text, 'exhausted'::text, 'opted_out'::text, 'handoff'::text]))),
    CONSTRAINT followup_enrollments_relogio_coerente CHECK ((((status = ANY (ARRAY['active'::text, 'waiting_reply'::text])) AND (next_eval_at IS NOT NULL)) OR (status = ANY (ARRAY['paused_handoff'::text, 'paused_manual'::text, 'completed'::text, 'cancelled'::text, 'dead'::text])))),
    CONSTRAINT followup_enrollments_status_valido CHECK ((status = ANY (ARRAY['active'::text, 'waiting_reply'::text, 'paused_handoff'::text, 'paused_manual'::text, 'completed'::text, 'cancelled'::text, 'dead'::text])))
);


ALTER TABLE public.followup_enrollments OWNER TO postgres;

--
-- Name: COLUMN followup_enrollments.next_eval_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.followup_enrollments.next_eval_at IS 'Quando este enrollment vence. DEFAULT now() do BANCO (migration 0147): quem agenda "para agora" deve OMITIR a coluna, porque o claim compara com now() do Postgres e o relógio do processo fica milissegundos à frente — o suficiente para o enrollment perder um tick inteiro (60s). Agendamento para o FUTURO continua passando valor explícito.';


--
-- Name: COLUMN followup_enrollments.timing_plan; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.followup_enrollments.timing_plan IS 'Plano de tempo das esperas adaptativas, decidido uma vez no acionamento do fluxo. null = sem plano (cai no max_ms de cada espera). Ver lib/followup/timing-plan.ts.';


--
-- Name: fn_claim_due_followup_enrollments(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_due_followup_enrollments(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.followup_enrollments
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with orgs as (
    -- Sem a condição de claim aqui de propósito: o lateral abaixo a aplica, e uma
    -- organização cujos vencidos estão todos com lease apenas devolve zero linhas.
    select distinct organization_id
      from followup_enrollments
     where status in ('active','waiting_reply')
       and next_eval_at <= now()
  ),
  fila as (
    select f.id, f.next_eval_at, f.posicao_na_org
      from orgs
      cross join lateral (
        select d.id,
               d.next_eval_at,
               row_number() over (order by d.next_eval_at) as posicao_na_org
          from followup_enrollments d
         where d.organization_id = orgs.organization_id
           and d.status in ('active','waiting_reply')
           and d.next_eval_at <= now()
           and (d.claimed_until is null or d.claimed_until < now())
         order by d.next_eval_at
         limit p_limit
      ) f
  ),
  escolhidos as (
    -- O rodízio: posição 1 de todas as organizações, depois a 2 de todas, etc.
    -- Empate na mesma posição vai para quem esperou mais.
    select id from fila order by posicao_na_org, next_eval_at limit p_limit
  ),
  travados as (
    select e.id from followup_enrollments e
     where e.id in (select id from escolhidos)
     for update skip locked
  )
  update followup_enrollments e
     set claimed_until = now() + make_interval(secs => p_lease_seconds),
         updated_at = now()
   where e.id in (select id from travados)
     -- A condição de lease É REPETIDA AQUI, e não é redundante com a CTE `fila`.
     -- Sem ela, duas conexões simultâneas reclamam as MESMAS linhas: a segunda
     -- espera o lock da primeira, e quando ele sai o Postgres (READ COMMITTED)
     -- reavalia só o WHERE do UPDATE — que não olhava `claimed_until` — e grava
     -- por cima. O `skip locked` da CTE não salva: as duas materializam a mesma
     -- lista antes de qualquer lock existir. Medido: interseção de 5 em 5 no
     -- invariante de concorrência (followup-schema.test.ts).
     and (e.claimed_until is null or e.claimed_until < now())
  returning e.*;
$$;


ALTER FUNCTION public.fn_claim_due_followup_enrollments(p_limit integer, p_lease_seconds integer) OWNER TO postgres;

