--
-- Name: fn_conversation_assign(uuid, uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_conversation_assign(p_organization_id uuid, p_conversation_id uuid, p_to_user_id uuid, p_reason text, p_expected_assignee uuid DEFAULT NULL::uuid, p_enforce_expected boolean DEFAULT false) RETURNS SETOF public.conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_from uuid;
  v_conv public.conversations%rowtype;
begin
  if auth.uid() is not null
     and not public.fn_role_at_least(p_organization_id, 'agent') then
    raise exception 'caller_not_authorized_for_org'
      using hint = 'caller must be an active agent+ member of the organization';
  end if;

  if p_to_user_id is not null then
    if coalesce(public.fn_member_role_in_org(p_to_user_id, p_organization_id), 'none')
         not in ('agent','manager','admin') then
      raise exception 'assignee_not_eligible_member'
        using hint = 'target must be an active agent+ member of the organization';
    end if;
  end if;

  select assigned_to_user_id into v_from
    from public.conversations
   where id = p_conversation_id
     and organization_id = p_organization_id
   for update;

  if not found then
    return;
  end if;

  if p_enforce_expected and v_from is distinct from p_expected_assignee then
    return;
  end if;

  update public.conversations
     set assigned_to_user_id = p_to_user_id,
         assigned_at = case when p_to_user_id is null then null else now() end,
         assignee_kind = case when p_to_user_id is null then null else 'user' end,
         status = case when p_to_user_id is null then 'open' else 'claimed' end,
         status_changed_at = now(),
         unread_count_for_assignee = 0,
         -- A trava só é solta por quem a pôs. `last_handoff_at` é o discriminador
         -- que já existe: uma ESCALAÇÃO o carimba (`performHumanHandoff` e
         -- `triggerHandoff`), um humano ASSUMINDO não. Sem esta condição, o
         -- release apagaria o silêncio de uma conversa que a IA escalou — e o
         -- caminho legado (`triggerHandoff`, usado pelo MCP, pelo handler de
         -- sentimento, pelo worker e pelo teto de gasto) NÃO grava
         -- `contacts.force_human`, então ali o silêncio é a ÚNICA trava. Medido:
         -- `grep -n force_human lib/ai/handoff/orchestrator.ts` → rc=1.
         -- Soltar de propósito é o botão "Devolver ao automático"
         -- (`devolverAtendimentoAoAgente`), que limpa as três travas de uma vez.
         bot_silenced_until = case
           when p_reason = 'routing'  then bot_silenced_until
           when p_to_user_id is null  then (case when last_handoff_at is null
                                                 then null
                                                 else bot_silenced_until end)
           else 'infinity'::timestamptz
         end,
         updated_at = now()
   where id = p_conversation_id
   returning * into v_conv;

  insert into public.conversation_assignment_events
    (organization_id, conversation_id, from_user_id, to_user_id, changed_by, reason)
  values
    (p_organization_id, p_conversation_id, v_from, p_to_user_id, auth.uid(), p_reason);

  return next v_conv;
end;
$$;


ALTER FUNCTION public.fn_conversation_assign(p_organization_id uuid, p_conversation_id uuid, p_to_user_id uuid, p_reason text, p_expected_assignee uuid, p_enforce_expected boolean) OWNER TO postgres;

--
-- Name: fn_crm_lead_close_on_stage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crm_lead_close_on_stage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_is_won  boolean;
  v_is_lost boolean;
begin
  if tg_op = 'UPDATE'
     and new.stage_id is not distinct from old.stage_id
     and new.status   is not distinct from old.status then
    return new;
  end if;

  select is_won, is_lost into v_is_won, v_is_lost
    from public.crm_stages where id = new.stage_id;

  if v_is_won then
    new.status := 'won';
    new.closed_at := coalesce(new.closed_at, now());
  elsif v_is_lost then
    new.status := 'lost';
    new.closed_at := coalesce(new.closed_at, now());
  else
    if tg_op = 'UPDATE' and old.status in ('won','lost') then
      new.status := 'open';
      new.closed_at := null;
    end if;
  end if;
  return new;
end$$;


ALTER FUNCTION public.fn_crm_lead_close_on_stage() OWNER TO postgres;

--
-- Name: fn_decrypt_oauth(bytea); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_decrypt_oauth(ciphertext bytea) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  k text := private.fn_oauth_key();
begin
  return pgp_sym_decrypt(ciphertext, k);
end$$;


ALTER FUNCTION public.fn_decrypt_oauth(ciphertext bytea) OWNER TO postgres;

--
-- Name: fn_definir_logo_da_organizacao(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_linhas integer;
  v_path   text;
begin
  if p_org is null or p_actor is null then
    raise exception 'logo_da_organizacao_argumento_nulo'
      using errcode = '22023';
  end if;

  v_path := nullif(btrim(coalesce(p_path, '')), '');

  -- O PREFIXO ASSEVERADO DENTRO DO BANCO — o gate que sobrevive ao segundo
  -- chamador. A rota monta o caminho a partir da organização resolvida do
  -- cookie, mas "a rota monta certo" é promessa de UM chamador. Sem esta linha,
  -- um caminho de outro escopo (o `platform/...` que qualquer pessoa lê no HTML
  -- da tela de login) entraria como logo da organização — e o delete-on-replace
  -- da rota, rodando como `service_role`, apagaria o logo da instalação inteira
  -- na troca seguinte.
  if v_path is not null
     and v_path !~ ('^' || p_org::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(png|jpg)$')
  then
    raise exception 'logo_da_organizacao_caminho_fora_do_escopo'
      using errcode = '22023';
  end if;

  if not exists (
       select 1 from public.user_organizations uo
        where uo.user_id = p_actor
          and uo.organization_id = p_org
          and uo.role = 'admin'
          and uo.revoked_at is null
     )
     and not exists (
       select 1 from public.platform_admins pa
        where pa.user_id = p_actor
          and pa.revoked_at is null
     )
  then
    raise exception 'logo_da_organizacao_sem_permissao'
      using errcode = '42501';
  end if;

  -- Merge no CAMPO. `jsonb_set` direto em '{branding,logo_path}' NÃO serviria:
  -- com `branding` ausente, `create_missing` só cria a ÚLTIMA chave e o caminho
  -- intermediário faltando devolve o jsonb original intocado — silenciosamente.
  update public.organizations o
     set settings = case
           when v_path is null
             then jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    coalesce(o.settings -> 'branding', '{}'::jsonb) - 'logo_path', true)
           else jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    coalesce(o.settings -> 'branding', '{}'::jsonb)
                      || jsonb_build_object('logo_path', v_path), true)
         end
   where o.id = p_org;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$_$;


ALTER FUNCTION public.fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text) OWNER TO postgres;

--
-- Name: FUNCTION fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text) IS 'Grava (ou apaga) organizations.settings.branding.logo_path com merge no CAMPO — não toca em app_name, accent_hex nem nas demais chaves de settings. Assevera que o caminho começa pelo proprio organization_id: caminho de outro escopo levanta 22023. Papel insuficiente levanta 42501. Devolve linhas afetadas: 0 = a organização não existe. Chamador: app/api/v1/marca/logo/route.ts.';


--
-- Name: fn_definir_marca_da_organizacao(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_definir_marca_da_organizacao(p_org uuid, p_actor uuid, p_marca jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_linhas integer;
  v_hex    text;
  v_limpar boolean;
begin
  if p_org is null or p_actor is null then
    raise exception 'marca_da_organizacao_argumento_nulo'
      using errcode = '22023';
  end if;

  v_limpar := p_marca is null or jsonb_typeof(p_marca) = 'null';

  if not v_limpar and jsonb_typeof(p_marca) <> 'object' then
    raise exception 'marca_da_organizacao_forma_invalida: %', jsonb_typeof(p_marca)
      using errcode = '22023';
  end if;

  v_hex := nullif(p_marca ->> 'accent_hex', '');
  if v_hex is not null and v_hex !~ '^#[0-9a-f]{6}$' then
    raise exception 'marca_da_organizacao_accent_hex_invalido'
      using errcode = '22023';
  end if;

  if not exists (
       select 1 from public.user_organizations uo
        where uo.user_id = p_actor
          and uo.organization_id = p_org
          and uo.role = 'admin'
          and uo.revoked_at is null
     )
     and not exists (
       select 1 from public.platform_admins pa
        where pa.user_id = p_actor
          and pa.revoked_at is null
     )
  then
    raise exception 'marca_da_organizacao_sem_permissao'
      using errcode = '42501';
  end if;

  update public.organizations o
     set settings = case
           -- "Limpar" com logo gravado NÃO apaga o logo: o campo tem controle
           -- próprio na tela, e limpar nome+cor responde a OUTRA pergunta.
           when v_limpar and coalesce(o.settings #>> '{branding,logo_path}', '') = ''
             then coalesce(o.settings, '{}'::jsonb) - 'branding'
           when v_limpar
             then jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    jsonb_build_object('logo_path', o.settings #> '{branding,logo_path}'), true)
           -- `p_marca || preservado`: o lado DIREITO vence em `||`, então o
           -- `logo_path` gravado sobrevive à substituição do objeto.
           -- `jsonb_strip_nulls` SÓ no fragmento preservado — nunca em `p_marca`,
           -- cujo `app_name: null` é um valor com significado.
           else jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    p_marca || jsonb_strip_nulls(
                      jsonb_build_object('logo_path', o.settings #> '{branding,logo_path}')), true)
         end
   where o.id = p_org;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$_$;


ALTER FUNCTION public.fn_definir_marca_da_organizacao(p_org uuid, p_actor uuid, p_marca jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_definir_marca_da_organizacao(p_org uuid, p_actor uuid, p_marca jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_definir_marca_da_organizacao(p_org uuid, p_actor uuid, p_marca jsonb) IS 'Grava organizations.settings.branding com merge ATÔMICO (jsonb_set), sem tocar nas demais chaves do jsonb (llm, routing, visibility_mode, atrito, ai_dispatch_mode, canonical_conversation_tags, lost_reasons_extra, plan) e PRESERVANDO branding.logo_path, que tem escritor próprio (fn_definir_logo_da_organizacao, migration 0158). Devolve linhas afetadas: 0 = a organização não existe. Papel insuficiente levanta 42501. Chamador: app/actions/settings/updateMarcaDaOrganizacao.ts.';


--
-- Name: fn_demanda_abre_no_inbound(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_demanda_abre_no_inbound() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_demanda uuid;
begin
  if new.direction <> 'inbound' then
    return new;
  end if;

  select d.id into v_demanda
    from public.demandas d
   where d.organization_id = new.organization_id
     and d.contact_id = new.contact_id
     and d.fechada_em is null
   order by d.aberta_em desc
   limit 1;

  if v_demanda is null then
    insert into public.demandas
      (organization_id, contact_id, aberta_em, origem, estado, dono_kind)
    values
      (new.organization_id, new.contact_id, new.sent_at, 'inbound', 'aberta', 'ia')
    returning id into v_demanda;
  end if;

  -- O vínculo é por conversa: a mesma demanda acumula os canais por onde a
  -- pessoa falou (cap. 5 §5.4). `on conflict do nothing` porque a chave é o par.
  insert into public.demanda_conversas (organization_id, demanda_id, conversation_id)
  values (new.organization_id, v_demanda, new.conversation_id)
  on conflict do nothing;

  return new;
end;
$$;


ALTER FUNCTION public.fn_demanda_abre_no_inbound() OWNER TO postgres;

--
-- Name: fn_demanda_fecha_com_conversa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_demanda_fecha_com_conversa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status not in ('resolved', 'closed') or old.status = new.status then
    return new;
  end if;

  update public.demandas d
     set estado = 'resolvida',
         desfecho = 'resolvida',
         fechada_em = now(),
         updated_at = now()
   where d.organization_id = new.organization_id
     and d.fechada_em is null
     and exists (
       select 1 from public.demanda_conversas dc
        where dc.demanda_id = d.id and dc.conversation_id = new.id
     )
     -- Só fecha se TODAS as conversas da demanda estiverem encerradas: uma
     -- demanda que atravessou dois canais não acabou porque um deles fechou.
     and not exists (
       select 1
         from public.demanda_conversas dc2
         join public.conversations c2 on c2.id = dc2.conversation_id
        where dc2.demanda_id = d.id
          and c2.id <> new.id
          and c2.status not in ('resolved', 'closed')
     );

  return new;
end;
$$;


ALTER FUNCTION public.fn_demanda_fecha_com_conversa() OWNER TO postgres;

--
-- Name: fn_emit_agent_case_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_agent_case_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_contact_id uuid;
  v_tipo text;
begin
  v_tipo := case when tg_op = 'INSERT' then 'ai.case_opened' else 'ai.case_closed' end;

  -- O contato viaja no PAYLOAD porque ele sempre existe por schema
  -- (`agent_cases.conversation_id` é not null e `conversations.contact_id` é
  -- not null) e porque poupa o consumidor de uma ida ao banco. O consumidor
  -- mantém o fallback de buscar, para não confiar em convenção.
  select c.contact_id into v_contact_id
    from public.conversations c
   where c.id = new.conversation_id;

  perform public.emit_event(
    v_tipo,
    'agent_case',
    new.id,
    jsonb_build_object(
      'case_id',         new.id,
      'conversation_id', new.conversation_id,
      'contact_id',      v_contact_id,
      'lead_id',         new.lead_id,
      'agent_id',        new.agent_id,
      'source',          new.source,
      'status',          new.status
    ),
    '{}'::jsonb,
    new.organization_id   -- SEMPRE de `new`, nunca de parâmetro: é o filtro de tenant
  );
  return null;            -- AFTER trigger: o retorno é ignorado
end;
$$;


ALTER FUNCTION public.fn_emit_agent_case_event() OWNER TO postgres;

