--
-- Name: fn_emit_event_on_lead_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_event_on_lead_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    return new;
  end if;

  if new.status is distinct from old.status then
    if new.status = 'won' then
      perform public.fn_log_event(new.organization_id, 'lead.won',
        jsonb_build_object('lead_id', new.id, 'value_cents', new.value_cents));
    elsif new.status = 'lost' then
      perform public.fn_log_event(new.organization_id, 'lead.lost',
        jsonb_build_object('lead_id', new.id, 'lost_reason', new.lost_reason));
    elsif new.status = 'open' then
      perform public.fn_log_event(new.organization_id, 'lead.reopened',
        jsonb_build_object('lead_id', new.id));
    end if;
  end if;

  if new.owner_user_id is distinct from old.owner_user_id
     or new.owner_agent_id is distinct from old.owner_agent_id then
    perform public.fn_log_event(new.organization_id, 'lead.assigned',
      jsonb_build_object(
        'lead_id', new.id,
        'from_user_id', old.owner_user_id, 'to_user_id', new.owner_user_id,
        'from_agent_id', old.owner_agent_id, 'to_agent_id', new.owner_agent_id,
        'owner_kind', new.owner_kind));
  end if;

  return new;
end$$;


ALTER FUNCTION public.fn_emit_event_on_lead_change() OWNER TO postgres;

--
-- Name: fn_emit_message_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_message_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_event text;
begin
  if new.direction = 'inbound' then
    v_event := 'message.received';
  else
    v_event := case new.status
                 when 'sending' then 'message.sending'
                 when 'sent' then 'message.sent'
                 when 'failed' then 'message.failed'
                 else 'message.outbound'
               end;
  end if;

  perform public.fn_log_event(
    new.organization_id, v_event,
    jsonb_build_object(
      'message_id', new.id, 'conversation_id', new.conversation_id,
      'contact_id', new.contact_id, 'direction', new.direction,
      'type', new.type, 'status', new.status, 'external_id', new.external_id,
      'channel_session_id', new.channel_session_id,
      'body_preview', "left"(new.body, 280)
    )
  );
  return new;
end$$;


ALTER FUNCTION public.fn_emit_message_event() OWNER TO postgres;

--
-- Name: fn_encrypt_oauth(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_encrypt_oauth(plaintext text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  k text := private.fn_oauth_key();
begin
  if k is null or length(k) < 32 then
    raise exception 'NUVEMSHOP_OAUTH_ENCRYPTION_KEY ausente';
  end if;
  return pgp_sym_encrypt(plaintext, k, 'cipher-algo=aes256');
end$$;


ALTER FUNCTION public.fn_encrypt_oauth(plaintext text) OWNER TO postgres;

--
-- Name: fn_enrich_llm_call_attribution_and_cost(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enrich_llm_call_attribution_and_cost() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_conversation text;
  v_message text;
  v_input_price numeric;
  v_output_price numeric;
begin
  -- Todo job do agent-engine já leva conversation_id e inbound_message_id no
  -- payload. Resolver aqui cobre turno principal, classificadores e compaction
  -- sem obrigar cada call site a lembrar de copiar os dois campos.
  if new.job_id is not null
     and (new.conversation_id is null or new.message_id is null) then
    select
      j.payload ->> 'conversation_id',
      j.payload ->> 'inbound_message_id'
    into v_conversation, v_message
    from public.job_queue j
    where j.id = new.job_id
      and j.organization_id = new.organization_id
    limit 1;

    if new.conversation_id is null
       and v_conversation is not null
       and pg_input_is_valid(v_conversation, 'uuid') then
      new.conversation_id := v_conversation::uuid;
    end if;

    if new.message_id is null
       and v_message is not null
       and pg_input_is_valid(v_message, 'uuid') then
      new.message_id := v_message::uuid;
    end if;
  end if;

  -- Se o seam já calculou o custo (incluindo cache quando suportado), ele é a
  -- fonte mais fiel e nunca é sobrescrito pelo catálogo.
  if new.cost_cents is not null then
    new.cost_is_estimate := false;
    new.pricing_source := coalesce(new.pricing_source, 'runtime_pricing');
    return new;
  end if;

  -- Falha antes de usage não é tratada como "preço zero do modelo". O ledger
  -- mantém cost_cents NULL, mas marca que não houve tokens observados.
  if coalesce(new.input_tokens, 0) = 0 and coalesce(new.output_tokens, 0) = 0 then
    new.cost_is_estimate := false;
    new.pricing_source := coalesce(new.pricing_source, 'no_usage');
    return new;
  end if;

  -- Fallback: o catálogo usa CENTS por milhão de tokens. É estimativa porque
  -- não conhece, de forma portátil, descontos de cache/lotes ou tarifas
  -- especiais que alguns gateways aplicam.
  select
    m.input_price_per_million_cents,
    m.output_price_per_million_cents
  into v_input_price, v_output_price
  from public.ai_models m
  where m.provider = new.provider
    and m.model_id = new.model
    and m.deprecated_at is null
  limit 1;

  if v_input_price is not null and v_output_price is not null then
    new.cost_cents :=
      ((coalesce(new.input_tokens, 0)::numeric * v_input_price) +
       (coalesce(new.output_tokens, 0)::numeric * v_output_price)) / 1000000::numeric;
    new.cost_is_estimate := true;
    new.pricing_source := 'ai_models_catalog';
  else
    new.cost_is_estimate := false;
    new.pricing_source := 'unknown';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.fn_enrich_llm_call_attribution_and_cost() OWNER TO postgres;

