-- Name: ai_agent_versions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ai_agent_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
