    version_number integer NOT NULL,
    system_prompt text NOT NULL,
    provider text NOT NULL,
    model text NOT NULL,
    credential_id uuid,
    tool_ids text[] DEFAULT '{}'::text[] NOT NULL,
    trigger_config jsonb DEFAULT jsonb_build_object('events', jsonb_build_array('message'), 'filters', jsonb_build_object('ignore_groups', true, 'ignore_self', true, 'keyword_regex', NULL::unknown, 'business_hours', NULL::unknown), 'concurrency', 'one_per_conversation') NOT NULL,
    channel_session_id uuid NOT NULL,
    max_steps integer DEFAULT 10 NOT NULL,
    token_budget integer DEFAULT 50000 NOT NULL,
    cost_budget_cents integer DEFAULT 50 NOT NULL,
    history_message_window integer DEFAULT 20 NOT NULL,
    history_token_window integer DEFAULT 8000 NOT NULL,
    handoff_keywords text[] DEFAULT ARRAY['falar com humano'::text, 'atendente'::text, 'pessoa real'::text] NOT NULL,
    handoff_tool_enabled boolean DEFAULT true NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp with time zone,
    superseded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    followup jsonb DEFAULT '{"enabled": false, "flow_pointer_ids": []}'::jsonb NOT NULL,
    multimodal_input boolean DEFAULT true NOT NULL,
    video_frames_enabled boolean DEFAULT false NOT NULL,
    split_messages boolean DEFAULT true NOT NULL,
    split_max_chars integer DEFAULT 600 NOT NULL,
    cases_enabled boolean DEFAULT false NOT NULL,
    operator_enabled boolean DEFAULT false NOT NULL,
    operator_model text,
    operator_tool_ids text[] DEFAULT '{}'::text[] NOT NULL,
    pipeline_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    reasoning_effort text,
    CONSTRAINT ai_agent_versions_cost_budget_cents_check CHECK (((cost_budget_cents >= 1) AND (cost_budget_cents <= 10000))),
    CONSTRAINT ai_agent_versions_max_steps_check CHECK (((max_steps >= 1) AND (max_steps <= 25))),
    CONSTRAINT ai_agent_versions_provider_nao_vazio CHECK ((length(btrim(provider)) > 0)),
    CONSTRAINT ai_agent_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'superseded'::text, 'archived'::text]))),
    CONSTRAINT ai_agent_versions_token_budget_check CHECK (((token_budget >= 1000) AND (token_budget <= 500000)))
);


ALTER TABLE public.ai_agent_versions OWNER TO postgres;

--
-- Name: COLUMN ai_agent_versions.operator_enabled; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ai_agent_versions.operator_enabled IS 'Spec 16 §3.2: o papel Operador roda após o turno do Conversador. false = o registro básico segue por código determinístico (estado, follow-up prometido, timeline); o que se perde é o julgamento sobre as capacidades do catálogo.';


--
-- Name: COLUMN ai_agent_versions.operator_model; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ai_agent_versions.operator_model IS 'Modelo do papel Operador. NULL = herda o modelo do agente.';


--
-- Name: COLUMN ai_agent_versions.operator_tool_ids; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ai_agent_versions.operator_tool_ids IS 'Spec 16 §6: capacidades do papel Operador, independentes de `tool_ids` (do Conversador). Vazio = o papel roda mas não tem mão — estado legítimo: ele ainda registra promessa em aberto na Central.';


--
-- Name: COLUMN ai_agent_versions.pipeline_ids; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ai_agent_versions.pipeline_ids IS 'Funis em que ESTE agente pode escrever (mover, editar, encerrar, taguear). Vazio = NENHUM: falha fechada. Escopo de ESCRITA; leitura não é filtrada por aqui (declarado na spec 17 §5).';


