-- Name: ai_budgets; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ai_budgets (
    organization_id uuid NOT NULL,
    monthly_limit_cents integer DEFAULT 5000 NOT NULL,
    action_at_100pct text DEFAULT 'throttle'::text NOT NULL,
    alarm_threshold_pct integer DEFAULT 80 NOT NULL,
    current_month_consumed_cents numeric DEFAULT 0 NOT NULL,
    current_period_start date DEFAULT (date_trunc('month'::text, now()))::date NOT NULL,
    last_alarm_sent_at timestamp with time zone,
    is_throttled boolean DEFAULT false NOT NULL,
    is_disabled boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    enforcement_mode text DEFAULT 'off'::text NOT NULL,
    enforcement_effective_at timestamp with time zone,
    CONSTRAINT ai_budgets_action_at_100pct_check CHECK ((action_at_100pct = ANY (ARRAY['throttle'::text, 'disable'::text]))),
    CONSTRAINT ai_budgets_alarm_threshold_pct_check CHECK (((alarm_threshold_pct >= 50) AND (alarm_threshold_pct <= 99))),
    CONSTRAINT ai_budgets_bloquear_precisa_de_teto CHECK (((enforcement_mode <> 'bloquear'::text) OR (monthly_limit_cents >= 100))),
    CONSTRAINT ai_budgets_enforcement_mode_check CHECK ((enforcement_mode = ANY (ARRAY['off'::text, 'avisar'::text, 'bloquear'::text])))
);


ALTER TABLE public.ai_budgets OWNER TO postgres;

--
-- Name: COLUMN ai_budgets.enforcement_mode; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ai_budgets.enforcement_mode IS 'A INTENÇÃO, declarada por um admin — nunca inferida do valor do teto. off = só acompanhar (a IA nunca para por gasto); avisar = abre budget_warning ao passar do limiar e SEGUE; bloquear = recusa a chamada quando o gasto atinge o teto. Nasce off por DEFAULT do ALTER, e é por isso que ligar o teto no gate não estrangula quem herdou o DEFAULT 5000 de monthly_limit_cents. Escrito só por PATCH /api/v1/ai/budget (admin, auditado); lido por lib/agent-engine/edge/llm/credentials.ts.';


--
-- Name: COLUMN ai_budgets.enforcement_effective_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ai_budgets.enforcement_effective_at IS 'Carência: a partir de quando bloquear passa a valer de fato (now()+72h ao armar pela tela). Nasce NULL, e null <= now() é null — nunca verdadeiro —, então modo bloquear sem esta data ainda não bloqueia. Existe para que armar a proteção não seja um interruptor que corta o WhatsApp do negócio no mesmo instante, sem ninguém ver o aviso antes.';


