    CONSTRAINT contact_field_proposals_decisao_datada CHECK ((((status = 'pending'::text) AND (decided_at IS NULL)) OR ((status <> 'pending'::text) AND (decided_at IS NOT NULL)))),
    CONSTRAINT contact_field_proposals_prazo_no_futuro CHECK ((expires_at > proposed_at)),
    CONSTRAINT contact_field_proposals_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'dismissed'::text, 'expired'::text])))
);


ALTER TABLE public.contact_field_proposals OWNER TO postgres;

--
-- Name: TABLE contact_field_proposals; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.contact_field_proposals IS 'Dado do contato que a IA ouviu na conversa e propôs — aguardando confirmação humana (spec 17 §4b). SEMPRE com prazo: proposta que ninguém decide vira badge permanente, que simula atenção e adia a decisão. No vencimento sai da tela e vira item de caixa.';


--
-- Name: contacts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text,
    display_name text,
    email text,
    email_normalized text GENERATED ALWAYS AS (lower(TRIM(BOTH FROM email))) STORED,
    phone_number text,
    cpf_encrypted bytea,
    cpf_hash text,
    birthdate date,
    is_blocked boolean DEFAULT false NOT NULL,
    blocked_reason text,
    blocked_at timestamp with time zone,
    is_anonymized boolean DEFAULT false NOT NULL,
    anonymized_at timestamp with time zone,
    is_merged_into uuid,
    merged_at timestamp with time zone,
    consent jsonb DEFAULT jsonb_build_object('marketing', jsonb_build_object('granted_at', NULL::unknown, 'source', NULL::unknown, 'version', NULL::unknown), 'transactional', jsonb_build_object('granted_at', NULL::unknown, 'source', NULL::unknown, 'version', NULL::unknown), 'profiling', jsonb_build_object('granted_at', NULL::unknown, 'source', NULL::unknown, 'version', NULL::unknown)) NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    source_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id uuid,
    last_activity_at timestamp with time zone,
    force_human boolean DEFAULT false NOT NULL,
    wa_identity text GENERATED ALWAYS AS (
CASE
    WHEN (phone_number IS NOT NULL) THEN ('phone:'::text || phone_number)
    WHEN ((source_metadata ->> 'waha_lid'::text) IS NOT NULL) THEN ('lid:'::text || regexp_replace((source_metadata ->> 'waha_lid'::text), '@.*$'::text, ''::text))
    ELSE NULL::text
END) STORED,
    phone_lookup_at timestamp with time zone,
    locale text,
    avatar_storage_path text,
    avatar_updated_at timestamp with time zone,
    wa_lid text GENERATED ALWAYS AS (NULLIF(regexp_replace(COALESCE((source_metadata ->> 'waha_lid'::text), ''::text), '@.*$'::text, ''::text), ''::text)) STORED,
    CONSTRAINT contacts_anonymized_locked CHECK (((is_anonymized = false) OR ((is_anonymized = true) AND (anonymized_at IS NOT NULL)))),
    CONSTRAINT contacts_cpf_consistency CHECK (((cpf_encrypted IS NULL) = (cpf_hash IS NULL))),
    CONSTRAINT contacts_email_format CHECK (((email IS NULL) OR (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'::text))),
    CONSTRAINT contacts_phone_e164_format CHECK (((phone_number IS NULL) OR (phone_number ~ '^\+\d{8,15}$'::text)))
);


ALTER TABLE public.contacts OWNER TO postgres;

--
-- Name: TABLE contacts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.contacts IS 'Pessoa fisica no escopo de um tenant. CPF criptografado at-rest. is_anonymized irreversivel (L-04).';


--
-- Name: COLUMN contacts.phone_lookup_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.contacts.phone_lookup_at IS 'Última vez que se PERGUNTOU ao canal o telefone por trás da identidade opaca. NULL = nunca perguntado. Com valor e phone_number ainda null = o canal não sabia na ocasião.';


--
-- Name: COLUMN contacts.locale; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.contacts.locale IS 'Idioma preferido do contato (ex.: pt-BR, es-PY). NULL = herda o padrão da organização; o código resolve com fallback pt-BR.';


--
-- Name: COLUMN contacts.avatar_storage_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.contacts.avatar_storage_path IS 'Caminho da foto de perfil no bucket whatsapp-media. NULL = sem foto. Guardamos o arquivo, não a URL do WhatsApp, que expira em ~9 dias.';


--
-- Name: COLUMN contacts.avatar_updated_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.contacts.avatar_updated_at IS 'Quando a foto foi buscada pela última vez. NULL = nunca tentado. Usado pelo cron de refresh para escolher quem revisitar.';


--
-- Name: conversation_assignment_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.conversation_assignment_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
