    CONSTRAINT conversation_assignment_events_reason_check CHECK ((reason = ANY (ARRAY['claim'::text, 'transfer'::text, 'release'::text, 'routing'::text, 'handoff'::text])))
);


ALTER TABLE public.conversation_assignment_events OWNER TO postgres;

--
-- Name: conversation_notes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.conversation_notes (
