    created_by_user_id uuid,
    created_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.conversation_notes OWNER TO postgres;

--
-- Name: crm_lead_activities; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_lead_activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    lead_id uuid NOT NULL,
    contact_id uuid,
    source_module text NOT NULL,
    source_id uuid,
    type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    performed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    performed_by_user_id uuid,
    actor_kind text,
    actor_agent_id uuid,
    reason text,
    evidence jsonb,
    CONSTRAINT crm_lead_activities_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['user'::text, 'ai'::text, 'system'::text, 'rule'::text, 'contact'::text]))),
    CONSTRAINT crm_lead_activities_ai_needs_evidence CHECK (((actor_kind <> 'ai'::text) OR (COALESCE(jsonb_array_length((evidence -> 'run_ids'::text)), 0) > 0) OR (COALESCE(jsonb_array_length((evidence -> 'trace_ids'::text)), 0) > 0) OR (COALESCE(jsonb_array_length((evidence -> 'llm_call_ids'::text)), 0) > 0)))
);


ALTER TABLE public.crm_lead_activities OWNER TO postgres;

--
-- Name: COLUMN crm_lead_activities.actor_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_activities.actor_kind IS 'Quem agiu: user (humano do time) | ai (agente) | system (o produto) | rule (automação) | contact (a pessoa atendida). NUNCA "lead": lead aqui é o negócio.';


--
-- Name: COLUMN crm_lead_activities.reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_activities.reason IS 'Por que esta atividade existe, em texto legível. Sem PII: é exibido na timeline e exportado no LGPD.';


--
-- Name: COLUMN crm_lead_activities.evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_activities.evidence IS 'O que SUSTENTA a atividade (N referências), cada chave apontando para UMA tabela: run_ids→ai_agent_runs, trace_ids→o trace do turno, llm_call_ids→llm_calls. Não confundir com source_module/source_id, que é O QUE ORIGINOU (um ponteiro). evidence nunca repete o source_id — origem não é prova.';


--
-- Name: crm_lead_links; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_lead_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    lead_id uuid NOT NULL,
    target_kind text NOT NULL,
    target_id uuid NOT NULL,
    link_kind text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id uuid,
    CONSTRAINT crm_lead_links_target_kind_enum CHECK ((target_kind = ANY (ARRAY['order'::text, 'conversation'::text, 'message'::text, 'appointment'::text, 'contact'::text, 'lead'::text, 'external'::text])))
);


ALTER TABLE public.crm_lead_links OWNER TO postgres;

--
-- Name: crm_lead_reactivations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_lead_reactivations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lead_id uuid NOT NULL,
    organization_id uuid NOT NULL,
