    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    draft text,
    decided_at timestamp with time zone,
    decided_by_user_id uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_lead_reactivations_decisao_datada CHECK ((((status = 'pending'::text) AND (decided_at IS NULL)) OR ((status <> 'pending'::text) AND (decided_at IS NOT NULL)))),
    CONSTRAINT crm_lead_reactivations_prazo_no_futuro CHECK ((expires_at > proposed_at)),
    CONSTRAINT crm_lead_reactivations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'dismissed'::text, 'expired'::text])))
);


ALTER TABLE public.crm_lead_reactivations OWNER TO postgres;

--
-- Name: TABLE crm_lead_reactivations; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.crm_lead_reactivations IS 'Proposta de reativação de negócio esfriado (wave 7, cenário 23). SEMPRE com prazo: proposta que ninguém decide vira card parado com botão em cima, que simula atenção e adia a intervenção humana. No vencimento sai do card e vira item de caixa.';


--
-- Name: crm_lead_risk_states; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_lead_risk_states (
    lead_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    bucket text NOT NULL,
    since timestamp with time zone NOT NULL,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    cold_hours numeric NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_lead_risk_states_bucket_check CHECK ((bucket = ANY (ARRAY['em_dia'::text, 'em_voo'::text, 'em_risco'::text, 'critico'::text]))),
    CONSTRAINT crm_lead_risk_states_cold_hours_positivo CHECK ((cold_hours > (0)::numeric)),
    CONSTRAINT crm_lead_risk_states_since_no_passado CHECK ((since <= detected_at))
);


ALTER TABLE public.crm_lead_risk_states OWNER TO postgres;

--
-- Name: TABLE crm_lead_risk_states; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.crm_lead_risk_states IS 'Estado de risco por negócio (wave 7 — o ciclo). FORA de crm_leads pelos motivos da 0075 (pulso que mente, 409 fantasma), mas DENTRO da publicação supabase_realtime, ao contrário de crm_lead_scores: risco é mudança de estado, não telemetria. O escritor só grava quando o bucket muda.';


--
-- Name: crm_lead_scores; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_lead_scores (
    lead_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    ai_probability numeric(5,2),
    ai_probability_reason text,
    ai_probability_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    ai_probability_at timestamp with time zone,
    ai_probability_band text,
    ai_probability_band_since timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_lead_scores_band_check CHECK (((ai_probability_band IS NULL) OR (ai_probability_band = ANY (ARRAY['frio'::text, 'morno'::text, 'quente'::text])))),
    CONSTRAINT crm_lead_scores_band_coherence CHECK (((ai_probability_band IS NULL) OR (ai_probability IS NULL) OR ((ai_probability_band = 'quente'::text) AND (ai_probability >= (65)::numeric)) OR ((ai_probability_band = 'morno'::text) AND (ai_probability >= (35)::numeric) AND (ai_probability <= (75)::numeric)) OR ((ai_probability_band = 'frio'::text) AND (ai_probability <= (45)::numeric)))),
    CONSTRAINT crm_lead_scores_needs_reason CHECK (((ai_probability IS NULL) OR ((ai_probability_reason IS NOT NULL) AND (btrim(ai_probability_reason) <> ''::text) AND (COALESCE(jsonb_array_length((ai_probability_evidence -> 'factors'::text)), 0) > 0) AND (ai_probability_evidence @? '$."factors"[*]."ancora"'::jsonpath)))),
    CONSTRAINT crm_lead_scores_range CHECK (((ai_probability IS NULL) OR ((ai_probability >= (0)::numeric) AND (ai_probability <= (100)::numeric))))
);


ALTER TABLE public.crm_lead_scores OWNER TO postgres;

--
-- Name: TABLE crm_lead_scores; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.crm_lead_scores IS 'Score de probabilidade por lead, FORA de crm_leads de propósito. Ver o cabeçalho da migration 0075: trazer estes campos de volta reintroduz o pulso que mente (board assina crm_leads) e o 409 fantasma (trava otimista do move + trigger de updated_at). Fica FORA da publicação supabase_realtime — recálculo é telemetria e não deve pintar card; quem pinta é a atividade emitida na travessia de faixa.';


--
-- Name: COLUMN crm_lead_scores.ai_probability; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_scores.ai_probability IS 'Probabilidade 0-100 por FÓRMULA determinística sobre sinais que já existem — nunca chamada de modelo. Com fórmula, o reason é DERIVADO do cálculo e "número sem porquê" é impossível por construção; com modelo, a frase é gerada ao lado do número e a lei só pareceria cumprida. null = sinal insuficiente, e é estado legítimo: nunca zero.';


--
-- Name: COLUMN crm_lead_scores.ai_probability_reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_scores.ai_probability_reason IS 'O PORQUÊ em português, obrigatório por constraint quando há score. Existe para o humano poder DISCORDAR: sem razão citável o número é opinião sem apelação.';


--
-- Name: COLUMN crm_lead_scores.ai_probability_evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_scores.ai_probability_evidence IS 'O QUE SUSTENTA (N referências): activity_ids→crm_lead_activities, message_ids→messages, checkpoint_ids→lead_checkpoints. A constraint exige pelo menos uma — razão sem referência é adjetivo.';


--
-- Name: COLUMN crm_lead_scores.ai_probability_band; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_lead_scores.ai_probability_band IS 'Faixa exibida. Persistida porque histerese precisa da faixa anterior; o CHECK de coerência torna divergir do score IMPOSSÍVEL de gravar, não só improvável. Cortes em FAIXA_LIMITES (lib/kanban/score-band.ts), fonte única do CHECK, do emissor e da UI.';


--
-- Name: crm_leads; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_leads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    pipeline_id uuid NOT NULL,
    stage_id uuid NOT NULL,
    contact_id uuid,
    title text NOT NULL,
    description text,
    status text DEFAULT 'open'::text NOT NULL,
    lost_reason text,
    position_in_stage numeric DEFAULT 1000 NOT NULL,
    value_cents bigint,
    currency text DEFAULT 'BRL'::text,
    owner_user_id uuid,
    assigned_at timestamp with time zone,
    last_activity_at timestamp with time zone,
    expected_close_date date,
    closed_at timestamp with time zone,
    source text DEFAULT 'manual'::text NOT NULL,
    source_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    external_id text,
    custom_fields jsonb DEFAULT '{}'::jsonb NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id uuid,
    owner_kind text,
    owner_agent_id uuid,
    stage_changed_at timestamp with time zone DEFAULT now(),
    CONSTRAINT crm_leads_closed_at_consistency CHECK ((((status = 'open'::text) AND (closed_at IS NULL)) OR ((status = ANY (ARRAY['won'::text, 'lost'::text])) AND (closed_at IS NOT NULL)))),
    CONSTRAINT crm_leads_currency_iso CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT crm_leads_lost_reason_required CHECK (((status <> 'lost'::text) OR ((lost_reason IS NOT NULL) AND (length(lost_reason) > 0)))),
    CONSTRAINT crm_leads_owner_kind_check CHECK ((owner_kind = ANY (ARRAY['user'::text, 'ai'::text]))),
    CONSTRAINT crm_leads_owner_kind_coherence CHECK ((((owner_kind = 'user'::text) AND (owner_user_id IS NOT NULL) AND (owner_agent_id IS NULL)) OR ((owner_kind = 'ai'::text) AND (owner_agent_id IS NOT NULL) AND (owner_user_id IS NULL)) OR (owner_kind IS NULL))),
    CONSTRAINT crm_leads_status_enum CHECK ((status = ANY (ARRAY['open'::text, 'won'::text, 'lost'::text])))
);


ALTER TABLE public.crm_leads OWNER TO postgres;

--
-- Name: COLUMN crm_leads.stage_changed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_leads.stage_changed_at IS 'Quando o lead entrou no estágio atual. Carimbado por trigger. É o relógio de "tempo no estágio" do card — distinto de last_activity_at, que é "tempo sem resposta".';


--
-- Name: crm_pipelines; Type: TABLE; Schema: public; Owner: postgres
--

