    settings jsonb DEFAULT jsonb_build_object('fields', '[]'::jsonb, 'canonical_tags', '[]'::jsonb, 'lost_reasons', '[]'::jsonb, 'identity_resolution', jsonb_build_object('fields_in_priority_order', jsonb_build_array('cpf', 'phone_e164', 'email'))) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_pipelines_slug_format CHECK ((slug ~ '^[a-z0-9_-]{2,40}$'::text))
);


ALTER TABLE public.crm_pipelines OWNER TO postgres;

--
-- Name: crm_stages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    pipeline_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    description text,
    "position" numeric NOT NULL,
    color text,
    is_won boolean DEFAULT false NOT NULL,
    is_lost boolean DEFAULT false NOT NULL,
    is_archived boolean DEFAULT false NOT NULL,
    expected_duration_hours numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    requires_human boolean DEFAULT false NOT NULL,
    agent_stage_hint text,
    last_change_actor_kind text,
    last_change_at timestamp with time zone,
    CONSTRAINT crm_stages_agent_stage_hint_check CHECK (((agent_stage_hint IS NULL) OR (agent_stage_hint = ANY (ARRAY['new'::text, 'contacted'::text, 'qualifying'::text, 'qualified'::text, 'negotiating'::text, 'won'::text, 'lost'::text])))),
    CONSTRAINT crm_stages_color_format CHECK (((color IS NULL) OR (color ~ '^#[0-9a-fA-F]{6}$'::text))),
    CONSTRAINT crm_stages_hint_coerente_com_won_lost CHECK ((((agent_stage_hint <> 'won'::text) OR is_won) AND ((agent_stage_hint <> 'lost'::text) OR is_lost) AND ((NOT is_won) OR (agent_stage_hint IS NULL) OR (agent_stage_hint = 'won'::text)) AND ((NOT is_lost) OR (agent_stage_hint IS NULL) OR (agent_stage_hint = 'lost'::text)))),
    CONSTRAINT crm_stages_last_change_actor_kind_check CHECK ((last_change_actor_kind = ANY (ARRAY['user'::text, 'ai'::text, 'system'::text]))),
    CONSTRAINT crm_stages_slug_format CHECK ((slug ~ '^[a-z0-9_-]{2,40}$'::text)),
    CONSTRAINT crm_stages_won_lost_mutex CHECK ((NOT (is_won AND is_lost)))
);


ALTER TABLE public.crm_stages OWNER TO postgres;

--
-- Name: COLUMN crm_stages.agent_stage_hint; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_stages.agent_stage_hint IS 'A que passo do funil do AGENTE este estágio corresponde (lead_state.stage). NULL = não corresponde a nenhum, que é legítimo. Coerente com is_won/is_lost por CHECK — ver migration 0084.';


--
-- Name: COLUMN crm_stages.last_change_actor_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.crm_stages.last_change_actor_kind IS 'Espécie de quem fez a última mudança de configuração desta etapa: user | ai | system. NULL = anterior à 0101.';


--
-- Name: cron_jobs; Type: TABLE; Schema: public; Owner: postgres
