    CONSTRAINT cron_jobs_interval_ms_check CHECK (((interval_ms IS NULL) OR (interval_ms > 0))),
    CONSTRAINT cron_jobs_job_kind_check CHECK ((job_kind = ANY (ARRAY['inbound_turn'::text, 'followup_turn'::text, 'watchdog'::text, 'flywheel'::text, 'case_reply_turn'::text]))),
    CONSTRAINT cron_jobs_kind_check CHECK ((kind = ANY (ARRAY['at'::text, 'every'::text, 'cron'::text])))
);


ALTER TABLE public.cron_jobs OWNER TO postgres;

--
-- Name: COLUMN cron_jobs.cancelled_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.cron_jobs.cancelled_at IS 'Quando o retorno foi desmarcado. NULL = nunca cancelado (disparou ou ainda vai disparar). Distingue cancelado de disparado, que enabled=false sozinho não distingue.';


--
-- Name: COLUMN cron_jobs.cancel_reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.cron_jobs.cancel_reason IS 'Por que foi desmarcado, em texto curto e sem PII. Mesmo vocabulário de followup_enrollments.cancel_reason.';


--
-- Name: demanda_conversas; Type: TABLE; Schema: public; Owner: postgres
