CREATE POLICY webhook_sources_manager_write ON public.webhook_sources USING ((public.fn_is_platform_admin() OR ((organization_id IN ( SELECT public.fn_user_org_ids() AS fn_user_org_ids)) AND public.fn_role_at_least(organization_id, 'manager'::text)))) WITH CHECK ((public.fn_is_platform_admin() OR ((organization_id IN ( SELECT public.fn_user_org_ids() AS fn_user_org_ids)) AND public.fn_role_at_least(organization_id, 'manager'::text))));


--
-- Name: webhook_sources webhook_sources_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY webhook_sources_select ON public.webhook_sources FOR SELECT USING (((organization_id IN ( SELECT public.fn_user_org_ids() AS fn_user_org_ids)) OR public.fn_is_platform_admin()));


