--
-- Name: objects skill_assets_read; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY skill_assets_read ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = 'skill-assets'::text) AND ((split_part(name, '/'::text, 1) = 'platform'::text) OR (EXISTS ( SELECT 1
   FROM public.user_organizations uo
  WHERE ((uo.user_id = auth.uid()) AND (uo.revoked_at IS NULL) AND (uo.organization_id = (split_part(objects.name, '/'::text, 1))::uuid)))))));


--
-- Name: objects tenant_delete_ai_policy; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
